function baht(s){return "฿"+(s/100).toLocaleString("th-TH",{maximumFractionDigits:0})}
function fmt(h){return String(h).padStart(2,"0")+":00"} function isoAdd(date,n){let d=new Date(date+"T12:00:00");d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function thaiDate(d){return new Intl.DateTimeFormat("th-TH",{weekday:"long",day:"numeric",month:"short",year:"numeric"}).format(new Date(d+"T12:00:00"))}
function togglePass(){loginPass.type=loginPass.type==="password"?"text":"password"}
const C99_LOGIN_EMAIL_KEY="coachdi-login-email:v1";
function c99RememberedEmail(){try{return localStorage.getItem(C99_LOGIN_EMAIL_KEY)||""}catch(_){return""}}
function c99PrepareLogin(){const saved=c99RememberedEmail(),remember=document.getElementById("rememberLogin");if(saved&&window.loginId&&!loginId.value)loginId.value=saved;if(remember)remember.checked=CoachDiSession.keep(firebasePortalScope);window.loginId?.addEventListener("keydown",event=>{if(event.key==="Enter")window.loginPass?.focus()});window.loginPass?.addEventListener("keydown",event=>{if(event.key==="Enter")login()})}
async function login(){
 if(sessionLoginPending)return;
 try{
  const email=loginId.value.trim(),password=loginPass.value,remember=document.getElementById("rememberLogin")?.checked!==false;
  if(!email||!password)throw new Error("กรุณากรอก Email และ Password");
  sessionLoginPending=true;sessionLoginIntent=selectedLoginPortal;loginBtn.disabled=true;
  authMessage.textContent="กำลังเข้าสู่ระบบ...";
  await auth.setPersistence(remember?firebase.auth.Auth.Persistence.LOCAL:firebase.auth.Auth.Persistence.SESSION);
  CoachDiSession.preference(firebasePortalScope,remember);
  try{remember?localStorage.setItem(C99_LOGIN_EMAIL_KEY,email):localStorage.removeItem(C99_LOGIN_EMAIL_KEY)}catch(_){}
  await auth.signInWithEmailAndPassword(email,password);
 }catch(e){sessionLoginIntent=null;authMessage.textContent=thaiAuthError(e)}
 finally{sessionLoginPending=false;loginBtn.disabled=false}
}
async function registerAthlete(){try{let email=loginId.value.trim(),pass=loginPass.value;if(!email||pass.length<6)throw new Error("กรุณากรอก Email และ Password อย่างน้อย 6 ตัวอักษร");let c=await auth.createUserWithEmailAndPassword(email,pass);await db.ref(`users/${c.user.uid}`).set({role:"athlete",email,createdAt:firebase.database.ServerValue.TIMESTAMP});authMessage.textContent="สร้างบัญชีนักกีฬาแล้ว"}catch(e){authMessage.textContent=thaiAuthError(e)}}
async function resetPassword(){const email=loginId.value.trim().toLowerCase(),btn=document.getElementById('resetPasswordBtn');if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){authMessage.textContent='กรุณากรอก Email ที่ถูกต้องก่อนกดลืมรหัสผ่าน';return}try{btn.disabled=true;authMessage.textContent='กำลังส่งลิงก์ตั้งรหัสผ่านใหม่...';await auth.sendPasswordResetEmail(email);authMessage.textContent='ส่งคำขอแล้วจาก Firebase • กรุณาตรวจ Inbox และ Spam/Junk ของ Email นี้'}catch(e){console.error('password reset',e);authMessage.textContent=thaiAuthError(e)}finally{btn.disabled=false}}
function thaiAuthError(e){let m={"auth/invalid-credential":"Email หรือ Password ไม่ถูกต้อง","auth/user-not-found":"ไม่พบบัญชีผู้ใช้","auth/wrong-password":"Password ไม่ถูกต้อง","auth/email-already-in-use":"Email นี้มีบัญชีแล้ว","auth/too-many-requests":"ลองเข้าสู่ระบบหลายครั้งเกินไป กรุณารอสักครู่","auth/invalid-email":"รูปแบบ Email ไม่ถูกต้อง"};return m[e.code]||e.message||"เกิดข้อผิดพลาด"}
async function logout(){accountSession.begin(null);await auth.signOut();CoachDiSession.forget(firebasePortalScope)}
function enterPortal(){loginView.classList.add("hidden");portal.classList.remove("hidden");logoutBtn.classList.remove("hidden");roleBadge.textContent=state.role==="coach"?"Coach Portal":state.role==="admin"?"Admin":"Athlete";renderNav();state.role==="coach"?showCoach("dashboard"):showAthlete()}
async function loadFirebaseData(){let uid=state.user.uid;if(state.role==="coach"){state.coachId=uid;await ensureCoachDiId(uid)}else{await refreshCoachList(false);let cfg=await db.ref("appConfig/pilotCoachId").once("value");state.pilotCoachId=cfg.val();state.coachId=[state.coachId,state.pilotCoachId,state.coaches[0]?.uid].find(id=>state.coaches.some(p=>p.uid===id||p.aliasUids?.includes(id)))||''}if(!state.coachId&&state.role==="athlete"){authMessage.textContent="ยังไม่ได้ตั้ง Pilot Coach ใน appConfig/pilotCoachId";return}
 const cid=state.coachId;if(state.role==="coach")db.ref(`coachProfiles/${cid}`).on("value",x=>{state.coachProfile=x.val()||{};});db.ref(`coachVenues/${cid}`).on("value",x=>{let v=x.val();if(v)state.venues=Object.entries(v).map(([id,a])=>({id,...a})).concat([{id:"other",name:"สนามอื่น",icon:"🏢",maps:"",openStart:6,openEnd:24}]);if(state.role==="athlete")renderSchedule()});
 db.ref(`coachAvailability/${cid}`).on("value",x=>{if(x.val())state.availability={...state.availability,...x.val()}});
 db.ref(`coachPricing/${cid}`).on("value",x=>{if(x.val())state.pricing={...state.pricing,...x.val()}});
 db.ref(`coachPaymentAccounts/${cid}`).on("value",x=>{if(x.val())state.paymentAccount={...state.paymentAccount,...x.val()}});
 db.ref(`coachTimeOff/${cid}`).on("value",x=>{state.timeOff=Object.values(x.val()||{})});
 if(state.role==="coach")db.ref(`coachLocations/${cid}`).on("value",x=>{state.coachLocations=Object.entries(x.val()||{}).map(([id,v])=>({id,...v}))});
 const bookingRef=state.role==="admin"?db.ref("bookings"):state.role==="coach"?db.ref("bookings").orderByChild("coachId").equalTo(uid):db.ref("bookings").orderByChild("athleteId").equalTo(uid);bookingRef.on("value",x=>{let all=Object.entries(x.val()||{}).map(([id,b])=>({id,...b}));state.bookings=all;if(state.role==="athlete")state.allAthleteBookings=all;if(state.role==="coach"&&portal&&!portal.classList.contains("hidden"))showCoach("dashboard");if(state.role==="athlete"&&portal&&!portal.classList.contains("hidden")){renderSchedule();renderAthleteBookings();if(document.getElementById('s40AthleteDynamic'))s40RenderCurrentAthleteDynamic()}});
 if(state.role==="coach")db.ref(`auditLogs/${uid}`).limitToLast(100).on("value",x=>{state.auditLogs=Object.values(x.val()||{})});
}
async function ensureCoachDiId(uid){let snap=await db.ref(`coachProfiles/${uid}`).once("value"),p=snap.val()||{};if(p.coachDiId)return p.coachDiId;let all=await db.ref("coachProfiles").once("value"),max=0;Object.values(all.val()||{}).forEach(x=>{let m=String(x.coachDiId||"").match(/ID_(\d+)/);if(m)max=Math.max(max,Number(m[1]))});let id=`ID_${String(max+1).padStart(3,"0")}`;await db.ref(`coachProfiles/${uid}`).update({coachDiId:id,displayName:p.displayName||state.user?.displayName||state.user?.email?.split("@")[0]||"Coach",updatedAt:firebase.database.ServerValue.TIMESTAMP});return id}
async function refreshCoachList(render=true){let s=await db.ref("coachProfiles").once("value"),all=s.val()||{};state.coaches=Object.entries(all).map(([uid,p])=>({uid,...p})).filter(x=>!["suspended","pending_approval"].includes(x.status));if(render)renderCoachPicker()}
