function coachSport(c){return String(c.sport||c.category||c.sportCategory||"tennis").toLowerCase().replace(/[^a-z]/g,"")}
function selectSport(id){state.selectedSport=id;state.selectedCell=null;renderCoachDiscovery();let list=filteredCoaches();if(list.length&&!list.some(c=>c.uid===state.coachId))changeAthleteCoach(list[0].uid)}
function filteredCoaches(){let q=(document.getElementById("coachSearchInput")?.value||"").trim().toLowerCase();return state.coaches.filter(c=>{let sp=coachSport(c),target=state.selectedSport.replace(/[^a-z]/g,"");let sportOK=sp===target||(target==="pickleball"&&sp==="pickleball");let text=`${c.displayName||""} ${c.nameTh||""} ${c.nameEn||""} ${c.coachDiId||""}`.toLowerCase();return sportOK&&(!q||text.includes(q))})}
function renderCoachDiscovery(){let cats=document.getElementById("sportCats"),cards=document.getElementById("coachCards");if(!cats||!cards)return;cats.innerHTML=SPORTS.map(x=>`<button class="sportCat ${state.selectedSport===x.id?"active":""}" onclick="selectSport('${x.id}')"><span class="sportIcon">${x.icon}</span>${x.label}</button>`).join("");let list=filteredCoaches();cards.innerHTML=list.length?list.map(c=>{let name=c.displayName||c.nameTh||c.nameEn||"Coach",initial=name.slice(0,1).toUpperCase(),photo=c.photoURL||c.photo||c.image||"";return `<button class="coachCard ${c.uid===state.coachId?"active":""}" onclick="changeAthleteCoach('${c.uid}')">${photo?`<img class="coachAvatar" src="${photo}" alt="${name}">`:`<div class="coachAvatar">${initial}</div>`}<div class="coachCardName">${name}</div><div class="coachSport">${SPORTS.find(x=>x.id===state.selectedSport)?.label||""} • ${c.coachDiId||"Coach Di"}</div></button>`}).join(""):`<div class="coachEmpty">ยังไม่มีโค้ชใน Category นี้</div>`;let c=state.coaches.find(x=>x.uid===state.coachId);selectedCoachIdentity.textContent=c?`กำลังดูตาราง: ${c.displayName||c.nameTh||c.nameEn||"Coach"} • Coach Di ID: ${c.coachDiId||"กำลังตั้งค่า"}`:"เลือกโค้ชเพื่อดูตาราง"}
function renderCoachPicker(){renderCoachDiscovery()}
async function changeAthleteCoach(uid){if(!uid||uid===state.coachId)return;state.coachId=uid;state.selectedCell=null;await loadCoachScopedData(uid);renderCoachPicker()}
function loadCoachScopedData(cid){db.ref(`coachVenues/${cid}`).once("value").then(x=>{let v=x.val();if(v)state.venues=Object.entries(v).map(([id,a])=>({id,...a})).concat([{id:"other",name:"สนามอื่น",icon:"🏢",maps:"",openStart:6,openEnd:24}]);renderSchedule()});db.ref(`coachAvailability/${cid}`).once("value").then(x=>{if(x.val())state.availability={...state.availability,...x.val()};renderSchedule()});db.ref(`coachPricing/${cid}`).once("value").then(x=>{if(x.val())state.pricing={...state.pricing,...x.val()}});db.ref(`coachTimeOff/${cid}`).once("value").then(x=>{state.timeOff=Object.values(x.val()||{});renderSchedule()});renderSchedule()}
function showAthleteTab(tab){coachBookingTab.classList.toggle("hidden",tab!=="coach");courtBookingTab.classList.toggle("hidden",tab!=="court");coachTabBtn.classList.toggle("active",tab==="coach");courtTabBtn.classList.toggle("active",tab==="court")}
function openVisdaBooking(){window.location.assign(VISDA_LINK)}
async function ensureCoachApprovalRequest(user,userRef,record){
 if(selectedLoginPortal!=="coach")return record;
 const role=String(record?.role||"").trim().toLowerCase(),status=String(record?.status||"pending_approval").trim().toLowerCase();
 if((role&&role!=="coach")||status==="reviewing"||(role&&status!=="pending_approval"))return record;
 const email=String(user?.email||"").trim().toLowerCase();if(!email)return record;
 const stamp=firebase.database.ServerValue.TIMESTAMP,profileRef=db.ref(`coachProfiles/${user.uid}`),fallbackName=email.split("@")[0]||"Coach";
 if(!role){await userRef.set({role:"coach",status:"pending_approval",email,displayName:fallbackName,registrationComplete:false,createdAt:stamp});record=(await userRef.once("value")).val()||{}}
 let coachProfile=(await profileRef.once("value")).val();
 if(!coachProfile){await profileRef.set({displayName:record.displayName||fallbackName,nameEn:record.displayName||fallbackName,sport:"tennis",status:"pending_approval",registrationComplete:false,createdAt:stamp,updatedAt:stamp});coachProfile=(await profileRef.once("value")).val()||{}}
 const marked=Object.prototype.hasOwnProperty.call(record,"registrationComplete")||Object.prototype.hasOwnProperty.call(coachProfile,"registrationComplete");
 if(marked&&(record.registrationComplete!==true||coachProfile.registrationComplete!==true)){const complete={};complete[`users/${user.uid}/registrationComplete`]=true;complete[`users/${user.uid}/registrationCompletedAt`]=stamp;complete[`coachProfiles/${user.uid}/registrationComplete`]=true;complete[`coachProfiles/${user.uid}/updatedAt`]=stamp;await db.ref().update(complete)}
 return(await userRef.once("value")).val()||record
}
async function restoreCoachDiSession(user,loginIntent=null){
 accountSession.begin(user,true);
 const revision=++sessionBootstrapRevision;
 const current=()=>revision===sessionBootstrapRevision&&auth.currentUser?.uid===user?.uid;
 sessionBootstrapBusy=Boolean(user);state.authBootstrapError=null;
 if(!user){
  state.user=null;state.role=null;CoachDiSession.finish();portal.classList.add("hidden");
  loginView.classList.remove("hidden");logoutBtn.classList.add("hidden");selectLoginPortal(selectedLoginPortal);return;
 }
 state.user=user;state.role=null;
 CoachDiSession.status("กำลังโหลดบัญชีและข้อมูลของคุณ...");logoutBtn.classList.remove("hidden");
 try{
  // Firebase owns the credentials. Only the user's persistence preference and route are stored by this app.
  const remember=CoachDiSession.keep(firebasePortalScope);
  await auth.setPersistence(remember?firebase.auth.Auth.Persistence.LOCAL:firebase.auth.Auth.Persistence.SESSION);
  if(!current())return;
  const ref=db.ref(`users/${user.uid}`);let profile=(await ref.once("value")).val();
  if(!current())return;
  const restoredRole=String(profile?.role||"").trim().toLowerCase();
  if(!loginIntent&&["athlete","coach","admin"].includes(restoredRole))selectLoginPortal(restoredRole);
  if(selectedLoginPortal==="coach")profile=await ensureCoachApprovalRequest(user,ref,profile);
  if(!current())return;
  if(!profile?.role&&selectedLoginPortal==="athlete"){
   await ref.set({role:"athlete",status:"active",email:user.email||"",createdAt:firebase.database.ServerValue.TIMESTAMP});
   if(!current())return;profile=(await ref.once("value")).val();
  }
  if(!current())return;
  if(!profile?.role){await auth.signOut();authMessage.textContent=selectedLoginPortal==="coach"?"ระบบยังสร้างบัญชี Coach ไม่สำเร็จ กรุณาลองเข้าสู่ระบบอีกครั้ง":"บัญชีนี้ยังไม่ได้รับสิทธิ์ Admin — ให้กำหนด role = admin ใน Firebase";return}
  const role=String(profile.role).trim().toLowerCase();
  if(!["athlete","coach","admin"].includes(role)){await auth.signOut();authMessage.textContent="Role ของบัญชีนี้ไม่ถูกต้อง กรุณาติดต่อ Admin";return}
  // A restored session follows the verified profile; an explicit sign-in still validates the chosen portal.
  if(loginIntent&&role!==loginIntent){await auth.signOut();authMessage.textContent=`บัญชีนี้เป็น ${role} ไม่สามารถเข้า ${loginIntent} Portal ได้`;return}
  if(role==="coach"&&String(profile.status||"active").toLowerCase()!=="active"){
   const coachStatus=String(profile.status||"pending_approval").toLowerCase();await auth.signOut();
   authMessage.textContent=coachStatus==="rejected"?"บัญชี Coach ถูกปฏิเสธ กรุณาติดต่อ Admin":coachStatus==="suspended"?"บัญชี Coach ถูกระงับการใช้งาน กรุณาติดต่อ Admin":"บัญชี Coach ยังเปิดใช้งานไม่สมบูรณ์ กรุณาลองอีกครั้ง";return;
  }
  state.role=role;selectLoginPortal(role);CoachDiSession.remember(firebasePortalScope,role,remember);
  await loadFirebaseData();if(!current())return;
  CoachDiSession.finish();enterPortal();authMessage.textContent="เข้าสู่ระบบสำเร็จ";
 }catch(e){
  if(!current())return;
  console.error("Coach Di login bootstrap error",e);state.authBootstrapError=e;
  CoachDiSession.status("เชื่อมต่อข้อมูลไม่ได้ชั่วคราว กรุณาตรวจสอบอินเทอร์เน็ต คุณไม่ต้องกรอกรหัสผ่านใหม่",retryCoachDiSession);
 }finally{if(revision===sessionBootstrapRevision)sessionBootstrapBusy=false}
}
function retryCoachDiSession(){if(auth.currentUser&&!sessionBootstrapBusy)return restoreCoachDiSession(auth.currentUser)}
auth.onAuthStateChanged(user=>{const intent=user?sessionLoginIntent:null;if(user)sessionLoginIntent=null;return restoreCoachDiSession(user,intent)});
window.addEventListener('online',()=>{if(state.authBootstrapError)retryCoachDiSession()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.authBootstrapError)retryCoachDiSession()});
function renderNav(){
 if(state.role!=="coach"){
  const items=[["home","หน้าหลัก","⌂"],["coach","จองโค้ช","♟"],["court","จองสนาม","▦"],["mybookings","การจองของฉัน","☑"],["history","ประวัติการจอง","◷"]];
  sidebar.className="sidebar athleteSidebar";
  sidebar.innerHTML=`<div class="sideBrand"><span class="sideMark">Di</span><span>Coach Di</span></div>`+items.map(x=>`<button class="navbtn" data-athlete-page="${x[0]}" onclick="showAthleteMenu('${x[0]}')"><span class="navIcon">${x[2]}</span>${x[1]}</button>`).join("")+`<div class="sideDivider"></div><button class="navbtn sideLogout" onclick="logout()"><span class="navIcon">↪</span>ออกจากระบบ</button>`;
  mobileNav.className="mobileNav athleteMobile";mobileNav.innerHTML=items.map(x=>`<button data-athlete-mobile="${x[0]}" onclick="showAthleteMenu('${x[0]}')">${x[2]}<br>${x[1]}</button>`).join("");
  return;
 }
 sidebar.className="sidebar";mobileNav.className="mobileNav";let items=[["dashboard","Dashboard","⌂"],["schedule","ตารางสอน","▦"],["bookings","รายการจอง","☑"],["availability","จัดการเวลาว่าง","◷"],["timeoff","วันหยุด","☀"],["income","รายได้","฿"],["payments","การชำระเงิน","▣"],["profile","ประวัติโค้ช","●"],["settings","ตั้งค่า","⚙"]];sidebar.innerHTML=items.map(x=>`<button class="navbtn" data-page="${x[0]}" onclick="showCoach('${x[0]}')"><span>${x[2]}</span>${x[1]}</button>`).join("")+`<button class="navbtn" onclick=logout()>↪ ออกจากระบบ</button>`;mobileNav.innerHTML=items.slice(0,5).map(x=>`<button onclick="showCoach('${x[0]}')">${x[2]}<br>${x[1]}</button>`).join("")
}
function setAthleteNavActive(page){document.querySelectorAll('[data-athlete-page]').forEach(b=>b.classList.toggle('active',b.dataset.athletePage===page));document.querySelectorAll('[data-athlete-mobile]').forEach(b=>b.classList.toggle('active',b.dataset.athleteMobile===page))}
function showAthleteMenu(page){
 setAthleteNavActive(page);athletePage.classList.remove("hidden");coachPage.classList.add("hidden");
 const discovery=document.querySelector('.sportDiscovery'),schedule=document.querySelector('.scheduleShell'),historyCard=document.getElementById('athleteBookings')?.closest('.card'),hero=document.querySelector('.athleteHero'),tabs=document.querySelector('.athleteTabs');
 [discovery,schedule,historyCard,hero,tabs].forEach(el=>el&&el.classList.remove('hidden'));
 if(page==='court'){showAthleteTab('court');discovery?.classList.add('hidden');schedule?.classList.add('hidden');historyCard?.classList.add('hidden');return}
 showAthleteTab('coach');
 if(page==='home'){historyCard?.classList.add('hidden');return}
 if(page==='coach'){historyCard?.classList.add('hidden');hero?.classList.add('hidden');return}
 if(page==='mybookings'||page==='history'){discovery?.classList.add('hidden');schedule?.classList.add('hidden');tabs?.classList.add('hidden');hero?.classList.add('hidden');renderAthleteBookings();historyCard?.scrollIntoView({behavior:'smooth',block:'start'});return}
}
function showAthlete(){setTimeout(()=>{refreshCoachList().catch(()=>{})},0);athletePage.classList.remove("hidden");coachPage.classList.add("hidden");if(!state.weekStart||state.weekStart<TODAY)state.weekStart=TODAY;if(state.selectedDate<TODAY)state.selectedDate=TODAY;renderSchedule();renderAthleteBookings();setTimeout(()=>showAthleteMenu('home'),0)}
function changeWeek(n){let v=isoAdd(state.weekStart||TODAY,n);if(v<TODAY)v=TODAY;if(v>MAX_DATE)return;state.weekStart=v;state.selectedCell=null;renderSchedule()}
function getBooking(date,h){return state.bookings.find(b=>b.date===date&&b.start===h&&["confirmed","payment_submitted","payment_verified","pending_payment"].includes(b.status))}
function getCoachLoc(date,h){return state.coachLocations.find(x=>x.date===date&&x.start<=h&&x.end>h)}
function neighbors(date,h){let locs=state.coachLocations.filter(x=>x.date===date).sort((a,b)=>a.start-b.start);return {prev:[...locs].reverse().find(x=>x.end<=h)||null,next:locs.find(x=>x.start>=h+1)||null}}
function recommendReason(venueId,h){let n=neighbors(state.selectedDate,h),score=0,reasons=[];if(n.prev){let gap=(h-n.prev.end)*60,need=travelMinutes[n.prev.venueId][venueId]+state.availability.travelBufferMin;if(gap<need)return {ok:false,reason:`เดินทางจาก ${venueName(n.prev.venueId)} ต้องใช้ประมาณ ${travelMinutes[n.prev.venueId][venueId]} นาที + Buffer ${state.availability.travelBufferMin} นาที แต่มีเวลา ${gap} นาที`};score+=Math.max(0,120-need);reasons.push(`หลังคลาสที่ ${venueName(n.prev.venueId)}`)}if(n.next){let gap=(n.next.start-(h+1))*60,need=travelMinutes[venueId][n.next.venueId]+state.availability.travelBufferMin;if(gap<need)return {ok:false,reason:`ต้องเดินทางต่อไป ${venueName(n.next.venueId)} แต่มีเวลาไม่พอ`};score+=Math.max(0,120-need);reasons.push(`ก่อนคลาสที่ ${venueName(n.next.venueId)}`)}return {ok:true,score,reason:reasons.length?`เหมาะกับเส้นทาง ${reasons.join(" และ ")}`:"ไม่มีคลาสก่อน/หลัง จึงเดินทางได้"}}
function venueName(id,record){return record?.venueName||record?.venue||record?.customVenueName||state.venues.find(v=>v.id===id)?.name||"สนามอื่น"}
function sameVenue(a,b){if(!a||!b)return false;let an=String(venueName(a.venueId,a)).trim().toLowerCase(),bn=String(venueName(b.venueId,b)).trim().toLowerCase();return an&&bn&&an===bn}
function travelNeedMinutes(from,to){if(!from||!to||sameVenue(from,to))return 0;let matrix=travelMinutes?.[from.venueId]?.[to.venueId];return Number.isFinite(Number(matrix))?Number(matrix):45}
function previousCommitment(date,h){let all=[...state.coachLocations,...state.bookings.filter(b=>!["cancelled","refunded"].includes(b.status))].filter(x=>x.date===date&&Number(x.end)<=h).sort((a,b)=>Number(b.end)-Number(a.end));return all[0]||null}
function nextCommitment(date,h){let all=[...state.coachLocations,...state.bookings.filter(b=>!["cancelled","refunded"].includes(b.status))].filter(x=>x.date===date&&Number(x.start)>=h+1).sort((a,b)=>Number(a.start)-Number(b.start));return all[0]||null}
function travelCheck(date,h,venueId,venueLabel){let target={venueId,venueName:venueLabel||venueName(venueId)},prev=previousCommitment(date,h),next=nextCommitment(date,h),buffer=Number(state.availability.travelBufferMin||15);if(prev&&!sameVenue(prev,target)){let need=travelNeedMinutes(prev,target)+buffer,gap=(h-Number(prev.end))*60;if(gap<need)return {ok:false,prev,need,gap,reason:`ก่อนหน้านี้ Coach อยู่ที่ ${venueName(prev.venueId,prev)} และต้องใช้เวลาเดินทางประมาณ ${need} นาที`}}if(next&&!sameVenue(target,next)){let need=travelNeedMinutes(target,next)+buffer,gap=(Number(next.start)-(h+1))*60;if(gap<need)return {ok:false,next,need,gap,reason:`หลังคลาสนี้ Coach ต้องเดินทางไป ${venueName(next.venueId,next)} และต้องเผื่อประมาณ ${need} นาที`}}return {ok:true,prev,next,reason:prev&&sameVenue(prev,target)?`สนามเดียวกับคลาสก่อนหน้า (${venueName(prev.venueId,prev)}) จองต่อได้`:`เวลาเดินทางเพียงพอ`}}
function suggestNextSlots(date,h,venueId,venueLabel){let out=[];for(let hh=h+1;hh<=21&&out.length<3;hh++){if(getBooking(date,hh)||getCoachLoc(date,hh))continue;let c=travelCheck(date,hh,venueId,venueLabel);if(c.ok)out.push(hh)}return out}
function cellStatus(v,h){if(h<v.openStart||h>=v.openEnd)return {type:"unavailable",label:"—",reason:"สนามไม่เปิดให้บริการในช่วงเวลานี้"};let loc=getCoachLoc(state.selectedDate,h);if(loc)return loc.venueId===v.id?{type:"coach_location",label:"โค้ชอยู่สนามนี้",reason:"Coach Di มีคลาส/ประจำอยู่สนามนี้"}:{type:"unavailable",label:"—",reason:`Coach Di อยู่ที่ ${venueName(loc.venueId)} ในช่วงเวลานี้`};let bk=getBooking(state.selectedDate,h);if(bk)return bk.venueId===v.id?{type:"booked",label:"มีผู้จองแล้ว",reason:"Slot นี้ถูกจองแล้ว"}:{type:"unavailable",label:"—",reason:"Coach มี Booking ที่สนามอื่นในช่วงเวลานี้"};let r=recommendReason(v.id,h);if(!r.ok)return {type:"unavailable",label:"—",reason:r.reason};let candidates=state.venues.filter(x=>x.id!=="other"&&h>=x.openStart&&h<x.openEnd).map(x=>({id:x.id,...recommendReason(x.id,h)})).filter(x=>x.ok).sort((a,b)=>b.score-a.score);let best=candidates[0]?.id;return best===v.id?{type:"recommended",label:"สนามแนะนำ",reason:r.reason}:{type:"available",label:"ว่าง",reason:r.reason}}
function iconFor(t){return t==="coach_location"?"📍":t==="recommended"?"★":t==="available"?"●":t==="booked"?"■":"—"}
function shortThaiDate(d){return new Intl.DateTimeFormat("th-TH",{weekday:"short",day:"numeric",month:"short"}).format(new Date(d+"T12:00:00"))}
function isTimeOff(date,h){return state.timeOff.some(x=>date>=(x.startDate||x.date||"")&&date<=(x.endDate||x.date||"")&&(x.fullDay!==false||((x.startHour??0)<=h&&(x.endHour??24)>h)))}
function dayCellStatus(date,h){
 if(isTimeOff(date,h))return {type:"timeoff",label:"ไม่รับสอน",meta:"วันหยุด / ปิดเวลา"};
 let loc=getCoachLoc(date,h);if(loc)return {type:"coach_location",label:venueName(loc.venueId,loc),meta:"Coach อยู่สนามนี้",venueId:loc.venueId};
 let bk=getBooking(date,h);if(bk)return {type:"booked",label:"มีผู้จองแล้ว",meta:bk.venue||"Slot ไม่ว่าง",venueId:bk.venueId};
 if(h<state.availability.start||h>=state.availability.end)return {type:"unavailable",label:"—",meta:"ไม่เปิดรับสอน"};
 return {type:"available",label:"ว่าง",meta:"เลือกสนามเพื่อจอง"};
}
function renderSchedule(){
 let days=Array.from({length:5},(_,i)=>isoAdd(state.weekStart||TODAY,i)).filter(d=>d<=MAX_DATE),hours=Array.from({length:Math.max(0,state.availability.end-state.availability.start)},(_,i)=>i+state.availability.start);
 if(!days.length)return;
 weekRange.textContent=`${shortThaiDate(days[0])} – ${shortThaiDate(days[days.length-1])}`;
 let head=`<thead><tr><th class="timeHead">เวลา</th>${days.map(d=>{let dt=new Date(d+"T12:00:00"),parts=new Intl.DateTimeFormat("th-TH",{weekday:"short",day:"numeric",month:"short"}).formatToParts(dt),dow=parts.find(x=>x.type==="weekday")?.value||"",day=parts.find(x=>x.type==="day")?.value||"",mon=parts.find(x=>x.type==="month")?.value||"";return `<th class="dayHead ${d===TODAY?"today":""}" title="${shortThaiDate(d)}"><div class=dow>${dow}</div><div class=dom>${day}</div><div class="monthLabel">${mon}</div></th>`}).join("")}</tr></thead>`;
 let rows=hours.map(h=>`<tr><td class="timeCell">${fmt(h)}</td>${days.map(d=>{let s=dayCellStatus(d,h),disabled=["booked","timeoff","unavailable","coach_location"].includes(s.type),selected=state.selectedCell&&state.selectedCell.date===d&&state.selectedCell.h===h;return `<td><button class="daySlot ${s.type} ${selected?"selected":""}" ${disabled?"disabled":""} onclick="selectDateSlot('${d}',${h})" aria-label="${shortThaiDate(d)} ${fmt(h)} ${s.label}"><div class=venue><span class=dot>${s.type==="coach_location"?"📍":s.type==="booked"?"■":s.type==="available"?"●":"—"}</span>${s.label}</div><div class=meta>${selected?"เลือกเวลานี้":(s.meta||"")}</div></button></td>`}).join("")}</tr>`).join("");
 scheduleTable.innerHTML=head+`<tbody>${rows}</tbody>`;
}
function selectDateSlot(date,h){let s=dayCellStatus(date,h);if(s.type!=="available")return;state.selectedDate=date;state.selectedCell={date,h,venueId:null};renderSchedule();showInlineBookingTicket(date,h)}
function showInlineBookingTicket(date,h){let el=document.getElementById('inlineBookingTicket');if(!el)return;let coach=state.coaches.find(x=>x.uid===state.coachId),coachName=coach?(coach.displayName||coach.nameTh||coach.nameEn||'Coach'):'Coach';el.innerHTML=`<div class="ticketTop"><div><div class="ticketTitle">🎟️ Ticket การจอง</div><div class="ticketMeta"><b>${thaiDate(date)}</b> • ${fmt(h)}–${fmt(h+1)}<br>${coachName}</div></div><button class="pill" onclick="cancelInlineTicket()">✕</button></div><div class="ticketActions"><button class="pill primary" onclick="openVenueChoice('${date}',${h})">เลือกสนามและจอง</button></div>`;el.classList.remove('hidden');el.scrollIntoView({behavior:'smooth',block:'nearest'})}
function cancelInlineTicket(){state.selectedCell=null;let el=document.getElementById('inlineBookingTicket');if(el)el.classList.add('hidden');renderSchedule()}
function openVenueChoice(date,h){state.selectedDate=date;state.selectedCell={date,h,venueId:state.selectedCell?.venueId||null};let options=state.venues.filter(v=>v.id!=="other"&&h>=v.openStart&&h<v.openEnd).map(v=>`<option value="${v.id}">${v.name}</option>`).join("");sheetContent.innerHTML=`<h2 style="margin:0">เลือกเวลานี้</h2><p><b>${thaiDate(date)}</b><br>${fmt(h)}–${fmt(h+1)}</p><label class="label">เลือกสนามก่อนดำเนินการจอง</label><select id="bookingVenueSelect" class="field venueDropdown"><option value="">— กรุณาเลือกสนาม —</option>${options}<option value="other">สนามอื่น</option></select><div id="otherVenueBox"></div><div class="sheetActions"><button class="pill" onclick="closeSheet()">ยกเลิก</button><button class="pill primary" onclick="continueWithVenue(${h})">ดำเนินการต่อ</button></div>`;bookingVenueSelect.onchange=()=>{otherVenueBox.innerHTML=bookingVenueSelect.value==="other"?venueSearchHTML():""};sheetWrap.classList.remove("hidden")}
function continueWithVenue(h){let venueId=bookingVenueSelect.value;if(!venueId){alert("กรุณาเลือกสนามก่อน");return}if(venueId==="other"&&!resolveOtherVenue()){alert("กรุณาพิมพ์ชื่อสนามอย่างน้อย 2 ตัวอักษร หรือเลือกจากรายการ");return}state.selectedCell.venueId=venueId;openSheet(venueId,h,{type:"available",label:"เลือกเวลานี้",reason:"ยืนยันสนามแล้ว กรุณาตรวจสอบก่อนสร้าง Booking"})}
function openSheet(venueId,h,s){let v=state.venues.find(x=>x.id===venueId),n=neighbors(state.selectedDate,h);let other=venueId==="other";sheetContent.innerHTML=`<h2 style="margin:0">${s.label}</h2><p><b>${thaiDate(state.selectedDate)}</b><br>${fmt(h)}–${fmt(h+1)} • ${v.name}</p><div class=notice><b>เหตุผล</b><div class=small>${s.reason}</div></div><div class=card style="margin-top:10px"><b>เส้นทางของ Coach</b><div class=small>ก่อนหน้า: ${n.prev?venueName(n.prev.venueId)+" "+fmt(n.prev.start)+"–"+fmt(n.prev.end):"ไม่มี"}</div><div class=small>หลังจากนี้: ${n.next?venueName(n.next.venueId)+" "+fmt(n.next.start)+"–"+fmt(n.next.end):"ไม่มี"}</div></div>${other?venueSearchHTML():""}<div id=verifyResult></div><div class=sheetActions><button class=pill onclick=closeSheet()>ปิด</button><button id=chooseBtn class="pill primary" onclick="verifyAndBook('${venueId}',${h})">${other?"ค้นหาและเลือกสนาม":"เลือกสนามนี้"}</button></div>`;sheetWrap.classList.remove("hidden")}
function venueSearchHTML(){return `<label class=label>ชื่อสนามอื่น</label><input id=venueSearch class=field placeholder="พิมพ์ชื่อสนามเอง หรือเลือกจากรายการแนะนำ" oninput=searchVenue()><div class="small muted" style="margin-top:6px">หากไม่พบในรายการ สามารถใช้ชื่อที่พิมพ์เองได้</div><div id=venueResults class=searchResults></div>`}
function searchVenue(){let q=venueSearch.value.trim().toLowerCase();let rs=q?COURTS.filter(c=>(c.name+" "+c.province+" "+c.area).toLowerCase().includes(q)).slice(0,12):[];venueResults.innerHTML=rs.map((c,i)=>`<div class=searchItem onclick='chooseOtherCourt(${JSON.stringify(c)})'><b>${c.name}</b><div class="small muted">${c.area||""} ${c.province||""}</div></div>`).join("")}
let chosenOther=null;function chooseOtherCourt(c){chosenOther=c;venueSearch.value=c.name;venueResults.innerHTML=`<div class=ok><b>เลือก ${c.name}</b>${c.maps?`<br><a href="${c.maps}" target=_blank>ตรวจสอบสนาม / Google Maps ↗</a>`:""}</div>`}
function resolveOtherVenue(){let typed=String(document.getElementById('venueSearch')?.value||'').trim();if(chosenOther&&chosenOther.name===typed)return chosenOther;if(typed.length>=2){chosenOther={id:'other',name:typed,area:'',province:'',maps:''};return chosenOther}return null}
function verifyAndBook(venueId,h){
 if(venueId==="other"&&!resolveOtherVenue()){verifyResult.innerHTML='<div class=error>กรุณาพิมพ์ชื่อสนามอย่างน้อย 2 ตัวอักษร หรือเลือกจากรายการ</div>';return}
 chooseBtn.disabled=true;chooseBtn.textContent="กำลังตรวจสอบ Slot และเวลาเดินทาง…";
 setTimeout(()=>{let occupied=getBooking(state.selectedDate,h)||getCoachLoc(state.selectedDate,h);let court=venueId==="other"?chosenOther.name:venueName(venueId);if(occupied){verifyResult.innerHTML='<div class=error><b>ไม่สามารถจองได้</b><br>Coach มีตารางหรือ Booking อยู่ในช่วงเวลานี้</div>';chooseBtn.disabled=false;chooseBtn.textContent="ตรวจสอบอีกครั้ง";return}
 let travel=travelCheck(state.selectedDate,h,venueId,court);
 if(!travel.ok){let suggestions=suggestNextSlots(state.selectedDate,h,venueId,court);verifyResult.innerHTML=`<div class=error><b>เวลานี้ไม่เหมาะกับการเดินทาง</b><br>${travel.reason}</div><div class=notice style="margin-top:8px"><b>เวลาที่แนะนำ</b><br>${suggestions.length?suggestions.map(x=>`<button class="pill" style="margin:6px 5px 0 0" onclick="closeSheet();selectDateSlot('${state.selectedDate}',${x});openVenueChoice('${state.selectedDate}',${x})">${fmt(x)}–${fmt(x+1)}</button>`).join(""):"วันนี้ยังไม่พบเวลาถัดไปที่เหมาะสม กรุณาเลือกวันอื่น"}</div>`;chooseBtn.disabled=false;chooseBtn.textContent="ตรวจสอบอีกครั้ง";return}
 verifyResult.innerHTML=`<div class=ok><b>${travel.prev&&sameVenue(travel.prev,{venueId,venueName:court})?"สนามเดียวกับคลาสก่อนหน้า ✓":"เวลาเดินทางเหมาะสม ✓"}</b><br>${travel.reason}<br>สนาม: ${court}<br><label style="display:flex;gap:8px;margin-top:8px"><input id=courtConfirmed type=checkbox onchange="confirmCourtBooking('${venueId}',${h})"> ฉันจองสนามแล้ว</label>${venueId==="visda"?`<a href="${VISDA_LINK}" target=_blank><button class="pill" style="margin-top:8px">เช็คสนามว่าง / จอง VISDA ↗</button></a>`:""}</div>`;chooseBtn.disabled=true;chooseBtn.textContent="รอยืนยันการจองสนาม"},350)
}
function confirmCourtBooking(venueId,h){
 if(!courtConfirmed.checked)return;
 // Render payment step once. Repeated clicks must replace the same block, not append another block.
 let existing=document.getElementById("athletePaymentStep");
 let html=`<div id="athletePaymentStep" class="notice" style="margin-top:10px"><b>ขั้นตอนถัดไป: ส่งคำขอจองให้ Coach</b><br>ค่าคลาส ${baht(state.pricing.p60)}<br><span class="small">หลัง Coach Approve ระบบจะแจ้งกลับที่ “การจองของฉัน” เพื่อดำเนินการชำระเงิน</span><br><button id="submitCoachBookingBtn" class="pill orange" style="margin-top:8px" onclick="createBookingOnce('${venueId}',${h})">ส่งคำขอจอง Coach</button></div>`;
 if(existing){existing.outerHTML=html}else{verifyResult.insertAdjacentHTML("beforeend",html)}
}
function cleanFirebaseObject(obj){if(Array.isArray(obj))return obj.map(cleanFirebaseObject).filter(v=>v!==undefined);if(obj&&typeof obj==="object"&&obj!==firebase.database.ServerValue.TIMESTAMP){const out={};Object.entries(obj).forEach(([k,v])=>{if(v!==undefined){const c=cleanFirebaseObject(v);if(c!==undefined)out[k]=c}});return out}return obj}
let bookingSubmitLock=false;
async function createBookingOnce(venueId,h){
 if(bookingSubmitLock)return;
 let btn=document.getElementById("submitCoachBookingBtn");
 bookingSubmitLock=true;
 if(btn){btn.disabled=true;btn.textContent="กำลังส่งคำขอ..."}
 try{await createBooking(venueId,h)}finally{bookingSubmitLock=false;if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent="ส่งคำขอจอง Coach"}}
}

async function createBooking(venueId,h){
 if(!state.user||state.role!=="athlete")return;
 const coachId=String(state.coachId||"").trim();
 const athleteId=String(state.user.uid||"").trim();
 const bookingDate=String(state.selectedCell?.date||state.selectedDate||"").trim();
 if(!coachId){alert("กรุณาเลือกโค้ชก่อนเลือกเวลาและสร้าง Booking");return}
 if(!athleteId||!bookingDate||!Number.isFinite(Number(h))){alert("ข้อมูลการจองไม่ครบ กรุณาเลือกวันและเวลาใหม่อีกครั้ง");return}
 let court=venueId==="other"?(chosenOther?.name||"สนามอื่น"):(venueName(venueId)||"สนามที่เลือก");
 let dd=bookingDate.slice(-2),hh=String(Math.floor(Number(h))).padStart(2,"0"),suffix=Math.random().toString(36).slice(2,6).toUpperCase();
 let id=`${dd}${hh}${suffix}`;
 const p60=Number(state.pricing?.p60||0);
 let us=await db.ref(`users/${athleteId}`).once("value"),up=us.val()||{},phone=String(up.phone||"").trim();
 if(!phone){phone=(prompt("กรุณาระบุเบอร์โทรศัพท์สำหรับ Coach ติดต่อเรื่องการจอง")||"").trim();if(!phone){alert("กรุณาระบุเบอร์โทรศัพท์ก่อนส่งคำขอจอง");return}await db.ref(`users/${athleteId}`).update({phone});}
 let booking=cleanFirebaseObject({coachId,athleteId,athlete:up.displayName||up.name||state.user.email||"Athlete",athleteEmail:state.user.email||"",phone,date:bookingDate,start:Number(h),end:Number(h)+1,venueId:String(venueId||"other"),venue:court,status:"pending_coach_approval",approvalStatus:"pending",paymentStatus:"not_started",priceSatang:p60,travelFeeSatang:0,platformFeeSatang:4500,priceSnapshot:{p60},createdAt:firebase.database.ServerValue.TIMESTAMP});
 if(!booking.coachId){alert("ไม่พบ Coach ID กรุณาเลือกโค้ชใหม่");return}
 try{await db.ref(`bookings/${id}`).set(booking);await audit("booking_created",id,{coachId:booking.coachId,date:booking.date,start:booking.start});closeSheet();showBookingSuccessTicket(id,booking)}catch(e){console.error("Booking write failed",booking,e);alert("ไม่สามารถสร้าง Booking: "+(e?.message||"Unknown error"))}
}
function showBookingSuccessTicket(id,b){let el=document.getElementById("inlineBookingTicket");if(!el)return;el.innerHTML=`<div class="ticketTop"><div><div class="ticketTitle">✓ ส่งคำขอจองให้ Coach แล้ว</div><div class="ticketMeta"><b>${thaiDate(b.date)}</b> • ${fmt(b.start)}–${fmt(b.end)}<br>${b.venue}<br>Booking ID: ${id}</div></div><span class="status pending">รอ Coach Approve</span></div><div class="ticketActions"><button class="pill primary" onclick="showAthleteMenu('mybookings')">ดูการจองของฉัน</button><button class="pill" onclick="cancelInlineTicket()">ปิด Ticket</button></div>`;el.classList.remove("hidden");el.scrollIntoView({behavior:"smooth",block:"nearest"})}
function closeSheet(){sheetWrap.classList.add("hidden");chosenOther=null}
function renderAthleteBookings(){athleteBookings.innerHTML=state.bookings.filter(b=>b.athleteId===state.user?.uid).map(b=>`<div class=card><b>${b.date} • ${fmt(b.start)}–${fmt(b.end)}</b><div>${b.venue}</div><span class="status ${b.status==="confirmed"?"confirmed":"pending"}">${b.status}</span></div>`).join("")||'<div class=muted>ยังไม่มีประวัติการจอง</div>'}

function showCoach(page){athletePage.classList.add("hidden");coachPage.classList.remove("hidden");document.querySelectorAll(".navbtn").forEach(x=>x.classList.toggle("active",x.dataset.page===page));let fn={dashboard:coachDashboard,schedule:coachSchedule,bookings:coachBookings,availability:coachAvailability,timeoff:coachTimeOff,income:coachIncome,payments:coachPayments,profile:coachProfile,settings:coachSettings}[page]||coachDashboard;coachContent.innerHTML=fn()}
function coachDashboard(){let paid=state.bookings.filter(b=>["confirmed","completed"].includes(b.status)),gross=paid.reduce((a,b)=>a+b.priceSatang+b.travelFeeSatang,0),fee=paid.reduce((a,b)=>a+b.platformFeeSatang,0),today=state.bookings.filter(b=>b.date===TODAY);return `<h1 class=pageTitle>Dashboard</h1><p class=muted>สรุปงาน รายได้ และการเดินทางของ Coach Di</p><div class="grid g4"><div class=metric>คลาสวันนี้<b>${today.length}</b></div><div class=metric>รายได้วันนี้<b>${baht(gross)}</b></div><div class=metric>รายได้สุทธิ<b>${baht(gross-fee)}</b></div><div class=metric>รอรับ/ตรวจสอบ<b>${state.bookings.filter(b=>b.status==="payment_submitted").length}</b></div></div><div class="grid g3"><div class="card" style="grid-column:span 2"><h3>งานวันนี้</h3>${today.sort((a,b)=>a.start-b.start).map(b=>`<div class=card><b>${fmt(b.start)}–${fmt(b.end)} • ${b.athlete}</b><div>${b.venue}</div><div class=small>ควรออกเดินทางก่อน ${fmt(Math.max(6,b.start-1))} • ${b.paymentStatus}</div></div>`).join("")}</div><div class=card><h3>สรุปการสอน</h3><p>จำนวนคลาสทั้งหมด <b>${state.bookings.length}</b></p><p>จำนวนชั่วโมง <b>${state.bookings.length}</b></p><p>Average Revenue / Class <b>${paid.length?baht(Math.round(gross/paid.length)):baht(0)}</b></p><p>สนามที่ใช้บ่อย: <b>VISDA</b></p></div></div>`}
function coachSchedule(){return `<h1 class=pageTitle>ตารางสอน</h1><div class=card><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="pill primary">Daily</button><button class=pill>Weekly</button><button class=pill>Monthly</button><button class=pill>List</button></div></div>${bookingTable()}`}
function bookingTable(){return `<div class=card style="overflow:auto"><table class=tableSimple><thead><tr><th>Booking</th><th>นักกีฬา</th><th>สนาม</th><th>ราคา</th><th>Payment</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.bookings.map(b=>`<tr><td>${b.id}<br><span class=small>${b.date} ${fmt(b.start)}–${fmt(b.end)}</span></td><td>${b.athlete}<br><span class=small>${b.phone}</span></td><td>${b.venue}</td><td>${baht(b.priceSatang)}</td><td>${b.paymentStatus}</td><td>${b.status}</td><td>${b.status==="payment_submitted"?`<button class="pill primary" onclick="verifyPayment('${b.id}')">ยืนยันรับเงิน</button>`:"—"}</td></tr>`).join("")}</tbody></table></div>`}
function coachBookings(){return `<h1 class=pageTitle>รายการจอง</h1><p class=muted>ดูรายละเอียด ยืนยันการชำระ และจัดการสถานะ Booking</p>${bookingTable()}`}
async function verifyPayment(id){await db.ref(`bookings/${id}`).update({paymentStatus:"payment_verified",status:"confirmed",verifiedAt:firebase.database.ServerValue.TIMESTAMP});await audit("payment_verified",id);showCoach("bookings")}
function coachAvailability(){return `<h1 class=pageTitle>จัดการเวลาว่าง</h1><div class=card><div class=formgrid><label><span class=label>เวลาเริ่ม</span><input class=field value="06:00" type=time></label><label><span class=label>เวลาสิ้นสุด</span><input class=field value="24:00" type=time></label><label><span class=label>Slot Duration</span><select class=field><option>60 นาที</option><option>90 นาที</option><option>120 นาที</option></select></label><label><span class=label>Minimum Travel Buffer</span><input id=buffer class=field type=number value="${state.availability.travelBufferMin}"></label><label><span class=label>จำนวนคลาสสูงสุด/วัน</span><input class=field type=number value="${state.availability.maxClassesPerDay}"></label><label><span class=label>จองล่วงหน้า</span><input class=field value="30 วัน"></label></div><button class="pill primary" style="margin-top:12px" onclick="saveAvailability()">บันทึก</button></div>`}
async function saveAvailability(){let next={...state.availability,travelBufferMin:Number(buffer.value)};await db.ref(`coachAvailability/${state.user.uid}`).set(next);await audit("availability_changed",state.user.uid);alert("บันทึกแล้ว")}
function coachTimeOff(){return `<h1 class=pageTitle>วันหยุด</h1><div class=card><div class=formgrid><label><span class=label>วันที่เริ่ม</span><input id=offStart class=field type=date min="${TODAY}"></label><label><span class=label>วันที่สิ้นสุด</span><input id=offEnd class=field type=date min="${TODAY}"></label><label><span class=label>ประเภท</span><select id=offType class=field><option>วันหยุด</option><option>ลาป่วย</option><option>ลากิจ</option><option>เดินทาง</option><option>ไม่สะดวกรับสอน</option><option>อื่น ๆ</option></select></label><label><span class=label>หมายเหตุ</span><input id=offNote class=field></label></div><button class="pill primary" style="margin-top:12px" onclick=saveTimeOff()>เพิ่มวันหยุด</button><div id=offResult></div></div>`}
function saveTimeOff(){let affected=state.bookings.filter(b=>b.date>=offStart.value&&b.date<=offEnd.value&&b.status==="confirmed");if(affected.length){offResult.innerHTML=`<div class=error><b>พบ ${affected.length} Booking ที่ได้รับผลกระทบ</b><br>ระบบไม่ยกเลิกอัตโนมัติ กรุณาเสนอเวลาใหม่หรือดำเนินการ Refund</div>`;return}let id=db.ref(`coachTimeOff/${state.user.uid}`).push().key;db.ref(`coachTimeOff/${state.user.uid}/${id}`).set({coachId:state.user.uid,start:offStart.value,end:offEnd.value,type:offType.value,note:offNote.value,createdAt:firebase.database.ServerValue.TIMESTAMP});audit("timeoff_created",id);offResult.innerHTML='<div class=ok>เพิ่มวันหยุดและปิด Slot แล้ว</div>'}
function coachIncome(){let tx=state.bookings.filter(b=>["confirmed","completed"].includes(b.status));let gross=tx.reduce((a,b)=>a+b.priceSatang+b.travelFeeSatang,0),fees=tx.reduce((a,b)=>a+b.platformFeeSatang,0);return `<h1 class=pageTitle>รายได้</h1><div class="grid g4"><div class=metric>Gross Revenue<b>${baht(gross)}</b></div><div class=metric>Platform Fee<b>${baht(fees)}</b></div><div class=metric>Net Revenue<b>${baht(gross-fees)}</b></div><div class=metric>Pending<b>${baht(state.bookings.filter(b=>b.status==="payment_submitted").reduce((a,b)=>a+b.priceSatang,0))}</b></div></div><div class=card><button class=pill onclick=exportCSV()>Export CSV</button><table class=tableSimple><tr><th>Transaction</th><th>Booking</th><th>สนาม</th><th>Gross</th><th>Fee</th><th>Net</th></tr>${tx.map(b=>`<tr><td>TX-${b.id}</td><td>${b.id}</td><td>${b.venue}</td><td>${baht(b.priceSatang)}</td><td>${baht(b.platformFeeSatang)}</td><td>${baht(b.priceSatang-b.platformFeeSatang)}</td></tr>`).join("")}</table></div>`}
function exportCSV(){let rows=[["Booking ID","Date","Venue","Gross Satang","Platform Fee Satang"],...state.bookings.filter(b=>["confirmed","completed"].includes(b.status)).map(b=>[b.id,b.date,b.venue,b.priceSatang,b.platformFeeSatang])];let blob=new Blob([rows.map(r=>r.map(x=>`"${String(x).replaceAll('"','""')}"`).join(",")).join("\n")],{type:"text/csv"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="coach-di-income.csv";a.click()}
function coachPayments(){return `<h1 class=pageTitle>การชำระเงิน</h1><div class=card><h3>บัญชีรับเงิน</h3><p>${state.paymentAccount.bank} • ${state.paymentAccount.masked}</p><p>${state.paymentAccount.accountName}</p><div class=notice>UAT แสดงเฉพาะเลขบัญชีแบบ Mask และไม่บันทึกเลขเต็มลง Log</div></div>${bookingTable()}`}
function coachProfile(){let p=state.coachProfile||{};return `<h1 class=pageTitle>ประวัติโค้ช</h1><div class=card><div class=notice><b>Coach Di ID</b><div style="font-size:20px;font-weight:900;margin-top:4px">${p.coachDiId||"กำลังสร้าง..."}</div><div class=small>ID นี้ผูกกับ Firebase UID ของโค้ชและใช้ให้นักกีฬาเลือกโค้ช</div></div><div class=formgrid><label><span class=label>Display Name</span><input id=coachDisplayName class=field value="${p.displayName||""}" placeholder="เช่น Coach ตั้ม"></label><label><span class=label>ชื่อภาษาไทย</span><input id=coachNameTh class=field value="${p.nameTh||""}"></label><label><span class=label>ชื่อภาษาอังกฤษ</span><input id=coachNameEn class=field value="${p.nameEn||""}"></label><label><span class=label>Email</span><input class=field value="${state.user?.email||""}" disabled></label></div><label><span class=label>ประวัติแนะนำตัว</span><textarea id=coachBio class=field rows=4>${p.bio||""}</textarea></label><div style="margin-top:12px"><button class="pill primary" onclick="saveCoachProfile()">บันทึกประวัติ</button></div></div>`}
async function saveCoachProfile(){let id=await ensureCoachDiId(state.user.uid),next={...state.coachProfile,coachDiId:id,displayName:coachDisplayName.value.trim(),nameTh:coachNameTh.value.trim(),nameEn:coachNameEn.value.trim(),bio:coachBio.value.trim(),status:state.coachProfile.status||"draft",updatedAt:firebase.database.ServerValue.TIMESTAMP};await db.ref(`coachProfiles/${state.user.uid}`).update(next);state.coachProfile={...next,updatedAt:Date.now()};await audit("profile_changed",state.user.uid);alert("บันทึกประวัติโค้ชแล้ว") }
function coachSettings(){return `<h1 class=pageTitle>ตั้งค่า</h1><div class=card><h3>ราคาและแพ็กเกจ</h3><div class=formgrid><label><span class=label>60 นาที</span><input id=p60 class=field type=number value="${state.pricing.p60/100}"></label><label><span class=label>90 นาที</span><input id=p90 class=field type=number value="${state.pricing.p90/100}"></label><label><span class=label>120 นาที</span><input id=p120 class=field type=number value="${state.pricing.p120/100}"></label><label><span class=label>Payment Deadline</span><input class=field value="${state.paymentAccount.deadlineMin} นาที"></label></div><button class="pill primary" style="margin-top:12px" onclick=savePricing()>บันทึกราคา</button></div><div class=card><h3>Security / Audit Log</h3><div class=small>${state.auditLogs.slice().reverse().map(x=>`${x.at} • ${x.action} • ${x.target}`).join("<br>")||"ยังไม่มี Audit Event"}</div></div>`}
async function savePricing(){let old={...state.pricing},next={p60:Number(p60.value)*100,p90:Number(p90.value)*100,p120:Number(p120.value)*100};await db.ref(`coachPricing/${state.user.uid}`).set(next);await audit("pricing_changed",state.user.uid,{old,new:next});alert("บันทึกราคาใหม่แล้ว • Booking เดิมยังใช้ Price Snapshot เดิม")}
async function audit(action,target,change={}){if(!state.user)return;let id=db.ref(`auditLogs/${state.user.uid}`).push().key;let safeChange=JSON.parse(JSON.stringify(change,(k,v)=>/password|accountNumber|promptPay/i.test(k)?"[REDACTED]":v));await db.ref(`auditLogs/${state.user.uid}/${id}`).set({userId:state.user.uid,action,target,change:safeChange,at:firebase.database.ServerValue.TIMESTAMP,actor:state.role})}


/* Sprint 3.1: Coach onboarding schedule + payout verification */
function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
function timeToHour(v){let [h,m]=String(v||"00:00").split(":").map(Number);return h+(m||0)/60}
function coachSchedule(){
 const locs=[...state.coachLocations].sort((a,b)=>String(a.date).localeCompare(String(b.date))||Number(a.start)-Number(b.start));
 return `<h1 class=pageTitle>ตารางสอนของฉัน</h1><p class=muted>ลงตารางสอนประจำวันและสนามที่คุณอยู่ ระบบจะใช้ข้อมูลนี้ป้องกันการจองซ้ำและแสดงตำแหน่งให้ Athlete เห็นก่อนจอง</p>
 <div class=card><h3>เพิ่มตารางสอน</h3><div class=formgrid>
 <label><span class=label>วันที่</span><input id=locDate class=field type=date min="${TODAY}" value="${TODAY}"></label>
 <label><span class=label>สนาม</span><select id=locVenue class=field onchange="toggleCoachOtherVenue()">${state.venues.map(v=>`<option value="${esc(v.id)}">${esc(v.name)}</option>`).join("")}</select><input id=locOtherVenue class="field hidden" style="margin-top:8px" placeholder="ระบุชื่อสนามอื่น เช่น ABC Tennis Club"></label>
 <label><span class=label>เริ่ม</span><input id=locStart class=field type=time value="09:00"></label>
 <label><span class=label>สิ้นสุด</span><input id=locEnd class=field type=time value="10:00"></label></div>
 <div class=notice style="margin-top:12px">ครั้งแรกที่ Coach Login แนะนำให้ลงตารางที่มีอยู่เดิมให้ครบก่อนเปิดรับ Booking เพื่อป้องกันเวลาชนกัน</div>
 <button class="pill primary" style="margin-top:12px" onclick="saveCoachLocation()">+ เพิ่มลงตาราง</button><div id=locMsg></div></div>
 <div class=card><h3>ตารางที่ลงไว้</h3>${locs.length?`<table class=tableSimple><thead><tr><th>วันที่</th><th>เวลา</th><th>สนาม</th><th></th></tr></thead><tbody>${locs.map((x,i)=>`<tr><td>${esc(thaiDate(x.date))}</td><td>${fmt(x.start)}–${fmt(x.end)}</td><td>${esc(x.venueName||x.venue||x.venueId||"")}</td><td><button class=pill onclick="deleteCoachLocation('${esc(x.id||"")}','${i}')">ลบ</button></td></tr>`).join("")}</tbody></table>`:`<div class=notice>ยังไม่มีตารางสอน กรุณาลงตารางที่มีอยู่เดิมก่อนเริ่มรับ Booking</div>`}</div>${bookingTable()}`
}
function toggleCoachOtherVenue(){let other=document.getElementById("locOtherVenue");if(other)other.classList.toggle("hidden",locVenue.value!=="other")}
async function saveCoachLocation(){
 let date=locDate.value,start=timeToHour(locStart.value),end=timeToHour(locEnd.value),venueId=locVenue.value,venue=state.venues.find(v=>v.id===venueId),customVenueName=venueId==="other"?String(locOtherVenue?.value||"").trim():"";
 if(!date||!venueId||!(end>start)||(venueId==="other"&&!customVenueName)){locMsg.innerHTML='<div class=error>กรุณาตรวจสอบวันที่ สนาม เวลาเริ่ม–สิ้นสุด และระบุชื่อสนามกรณีเลือกสนามอื่น</div>';return}
 let overlapLoc=state.coachLocations.find(x=>x.date===date && start<Number(x.end) && end>Number(x.start));
 let overlapBooking=state.bookings.find(b=>b.date===date && !["cancelled","refunded"].includes(b.status) && start<Number(b.end) && end>Number(b.start));
 if(overlapLoc||overlapBooking){locMsg.innerHTML=`<div class=error><b>บันทึกไม่ได้: เวลาซ้ำ</b><br>${overlapBooking?"มี Booking อยู่แล้วในช่วงเวลานี้":"มีตารางสอนอื่นอยู่แล้วในช่วงเวลานี้"}</div>`;return}
 let ref=db.ref(`coachLocations/${state.user.uid}`).push(),item={id:ref.key,coachId:state.user.uid,date,start,end,venueId,venueName:customVenueName||venue?.name||venueId,customVenueName:customVenueName||null,source:"coach_manual",createdAt:firebase.database.ServerValue.TIMESTAMP};
 await ref.set(item);await audit("coach_schedule_created",ref.key,{date,start,end,venueId});locMsg.innerHTML='<div class=ok>เพิ่มตารางสอนแล้ว</div>'
}
async function deleteCoachLocation(id,index){let x=state.coachLocations[index];if(!x)return;let key=id||x.id;if(!key){alert("รายการเก่าไม่มี ID กรุณาลบจาก Firebase หรือบันทึกใหม่");return}let blocked=state.bookings.some(b=>b.date===x.date && !["cancelled","refunded"].includes(b.status) && Number(x.start)<Number(b.end) && Number(x.end)>Number(b.start));if(blocked){alert("ลบไม่ได้ เพราะมี Booking อยู่ในช่วงเวลานี้");return}await db.ref(`coachLocations/${state.user.uid}/${key}`).remove();await audit("coach_schedule_deleted",key)}

function coachPayments(){let a=state.paymentAccount||{},status=a.verificationStatus||"not_submitted";let badge=status==="approved"?'<span class="status confirmed">Verified</span>':status==="pending"?'<span class="status pending">รอ Admin Verify</span>':'<span class="status booked">ยังไม่ Verify</span>';return `<h1 class=pageTitle>บัญชีรับเงิน & Verification</h1><div class=card><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><h3>ข้อมูลบัญชี Coach</h3>${badge}</div><p class=muted>ชื่อบัญชีต้องตรงกับชื่อจริงของ Coach ก่อนเปิดใช้การรับชำระเงิน</p><div class=formgrid>
<label><span class=label>ธนาคาร</span><input id=payBank class=field value="${esc(a.bank||"")}" placeholder="เช่น KBank"></label>
<label><span class=label>เลขบัญชี</span><input id=payNumber class=field value="${esc(a.accountNumber||"")}" inputmode=numeric placeholder="เลขบัญชี"></label>
<label><span class=label>ชื่อจริง Coach</span><input id=payCoachName class=field value="${esc(a.coachLegalName||state.coachProfile?.nameTh||"")}"></label>
<label><span class=label>ชื่อบัญชีธนาคาร</span><input id=payAccountName class=field value="${esc(a.accountName||"")}"></label></div>
<label><span class=label>แนบ QR Code รับเงิน</span><input id=payQR class=field type=file accept="image/png,image/jpeg,image/webp" onchange="previewQR(this)"></label><div id=qrPreview>${a.qrDataUrl?`<img src="${a.qrDataUrl}" style="max-width:220px;max-height:220px;border-radius:14px;margin-top:10px">`:""}</div>
<div class=notice style="margin-top:12px">รองรับไฟล์รูป JPG, PNG และ WEBP ขนาดไม่เกิน 3 MB</div>
<button class="pill primary" style="margin-top:12px" onclick="submitPaymentVerification()">ส่งให้ Admin Verify</button><div id=payMsg></div></div>`}
let pendingQRData=null;
function previewQR(input){let f=input.files?.[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>3*1024*1024){input.value="";alert("รองรับ JPG, PNG หรือ WEBP ขนาดไม่เกิน 3 MB");return}let r=new FileReader();r.onload=()=>{pendingQRData=r.result;qrPreview.innerHTML=`<img src="${r.result}" style="max-width:220px;max-height:220px;border-radius:14px;margin-top:10px">`};r.readAsDataURL(f)}
async function submitPaymentVerification(){let bank=payBank.value.trim(),accountNumber=payNumber.value.replace(/\D/g,""),coachLegalName=payCoachName.value.trim(),accountName=payAccountName.value.trim();if(!bank||!accountNumber||!coachLegalName||!accountName){payMsg.innerHTML='<div class=error>กรุณากรอกข้อมูลบัญชีให้ครบ</div>';return}if(accountNumber.length<8||accountNumber.length>20){payMsg.innerHTML='<div class=error>เลขบัญชีต้องมี 8–20 หลัก</div>';return}let old=state.paymentAccount||{};let next={bank,accountNumber,masked:accountNumber.length>4?"•••• "+accountNumber.slice(-4):accountNumber,coachLegalName,accountName,qrDataUrl:pendingQRData||old.qrDataUrl||"",verificationStatus:"pending",submittedAt:firebase.database.ServerValue.TIMESTAMP,verifiedBy:null,verifiedAt:null,rejectionReason:null};await db.ref(`coachPaymentAccounts/${state.user.uid}`).set(next);state.paymentAccount={...next,submittedAt:Date.now()};await audit("payout_verification_submitted",state.user.uid,{bank,coachLegalName,accountName});payMsg.innerHTML='<div class=ok>ส่งให้ Admin ตรวจสอบแล้ว</div>';showCoach("payments")}

function adminDashboard(){return `<h1 class=pageTitle>Admin Verification</h1><p class=muted>ตรวจสอบชื่อจริง Coach เทียบกับชื่อบัญชี และ QR Code ก่อนอนุมัติ</p><div id=adminVerifyList class=card>กำลังโหลด...</div>`}
async function loadAdminVerification(){let [acc,prof]=await Promise.all([db.ref("coachPaymentAccounts").once("value"),db.ref("coachProfiles").once("value")]),accounts=acc.val()||{},profiles=prof.val()||{};let rows=Object.entries(accounts).filter(([uid,a])=>a.verificationStatus==="pending");adminVerifyList.innerHTML=rows.length?rows.map(([uid,a])=>{let p=profiles[uid]||{};return `<div class=card><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><div><b>${esc(p.displayName||p.nameTh||uid)}</b><div class=small>${esc(p.coachDiId||uid)}</div></div><span class="status pending">Pending</span></div><hr><p>ชื่อจริง Coach: <b>${esc(a.coachLegalName)}</b></p><p>ชื่อบัญชี: <b>${esc(a.accountName)}</b></p><p>${esc(a.bank)} • ${esc(a.accountNumber||a.masked||'')}</p>${a.qrDataUrl?`<img src="${a.qrDataUrl}" style="max-width:180px;max-height:180px;border-radius:12px">`:"<p class=error>ไม่มี QR Code</p>"}<div style="display:flex;gap:8px;margin-top:12px"><button class="pill primary" onclick="adminVerifyPayout('${uid}',true)">✓ Approve</button><button class=pill onclick="adminVerifyPayout('${uid}',false)">✕ Reject</button></div></div>`}).join(""):'<div class=ok>ไม่มีรายการรอ Verify</div>'}
async function adminVerifyPayout(uid,approve){let reason="";if(!approve){reason=prompt("เหตุผลที่ Reject")||"ข้อมูลไม่ตรงกัน"}await db.ref(`coachPaymentAccounts/${uid}`).update({verificationStatus:approve?"approved":"rejected",verifiedBy:state.user.uid,verifiedAt:firebase.database.ServerValue.TIMESTAMP,rejectionReason:approve?null:reason});await audit(approve?"payout_verified":"payout_rejected",uid,{reason});await loadAdminVerification()}
function showAdmin(){athletePage.classList.add("hidden");coachPage.classList.remove("hidden");coachContent.innerHTML=adminDashboard();setTimeout(loadAdminVerification,0)}

// override navigation/bootstrap for admin and coach onboarding
const _enterPortal31=enterPortal;enterPortal=function(){loginView.classList.add("hidden");portal.classList.remove("hidden");logoutBtn.classList.remove("hidden");roleBadge.textContent=state.role==="coach"?"Coach Portal":state.role==="admin"?"Admin":"Athlete";renderNav();if(state.role==="coach")showCoach(state.coachLocations.length?"dashboard":"schedule");else if(state.role==="admin")showAdmin();else showAthlete()}
const _renderNav31=renderNav;renderNav=function(){if(state.role!=="admin")return _renderNav31();sidebar.className="sidebar";sidebar.innerHTML=`<button class="navbtn active" onclick="showAdmin()"><span>✓</span> Verify Coach</button><button class=navbtn onclick=logout()>↪ ออกจากระบบ</button>`;mobileNav.innerHTML=`<button onclick="showAdmin()">✓<br>Verify</button>`}


// ===== Sprint 3.3: Coach approval + timetable + dedicated test portals =====
function bookingStatusTH(b){return ({pending_coach_approval:"รอ Coach Approve",coach_approved:"Coach ยืนยันแล้ว",confirmed:"ยืนยันแล้ว",rejected_by_coach:"Coach ไม่รับการจอง",cancelled:"ยกเลิก"})[b.status]||b.status||"-"}
function coachBookingAction(b){
 if(b.status==="pending_coach_approval")return `<button class="pill primary" onclick="coachApproveBooking('${b.id}',true)">✓ Approve</button> <button class="pill" onclick="coachApproveBooking('${b.id}',false)">✕ Reject</button>`;
 if(b.status==="coach_approved"&&b.paymentStatus==="payment_submitted")return `<button class="pill primary" onclick="verifyPayment('${b.id}')">ยืนยันรับเงิน</button>`;
 return "—";
}
async function coachApproveBooking(id,approve){
 let b=state.bookings.find(x=>x.id===id);if(!b)return;
 if(!approve){let reason=prompt("เหตุผลที่ไม่รับการจอง")||"Coach ไม่สะดวกรับการจองนี้";await db.ref(`bookings/${id}`).update({status:"rejected_by_coach",approvalStatus:"rejected",coachApprovalReason:reason,coachRespondedAt:firebase.database.ServerValue.TIMESTAMP});await db.ref(`notifications/${b.athleteId}`).push().set({type:"booking_rejected",bookingId:id,senderId:state.user.uid,message:`Coach ไม่รับ Booking ${id}: ${reason}`,createdAt:firebase.database.ServerValue.TIMESTAMP,read:false});await audit("booking_rejected",id,{reason});return}
 await db.ref(`bookings/${id}`).update({status:"coach_approved",approvalStatus:"approved",coachApprovedAt:firebase.database.ServerValue.TIMESTAMP,paymentStatus:"pending_payment"});
 await db.ref(`notifications/${b.athleteId}`).push().set({type:"booking_approved",bookingId:id,senderId:state.user.uid,message:`Coach ยืนยัน Booking ${id} แล้ว กรุณาตรวจสอบการจองของฉัน`,createdAt:firebase.database.ServerValue.TIMESTAMP,read:false});await audit("booking_approved",id,{athleteId:b.athleteId});
}
bookingTable=function(){return `<div class=card style="overflow:auto"><table class=tableSimple><thead><tr><th>Booking</th><th>นักกีฬา / โทร</th><th>สนาม</th><th>ราคา</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.bookings.slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))||Number(a.start)-Number(b.start)).map(b=>`<tr><td><b>${esc(b.id)}</b><br><span class=small>${esc(b.date)} ${fmt(b.start)}–${fmt(b.end)}</span></td><td>${esc(b.athlete||b.athleteEmail||"Athlete")}<br><a href="tel:${esc(b.phone||"")}" class=small>${esc(b.phone||"ไม่มีเบอร์โทร")}</a></td><td>${esc(b.venue||"")}</td><td>${baht(Number(b.priceSatang||0))}</td><td><span class="status ${["confirmed","coach_approved"].includes(b.status)?"confirmed":"pending"}">${esc(bookingStatusTH(b))}</span></td><td>${coachBookingAction(b)}</td></tr>`).join("")}</tbody></table></div>`}
function coachTeachingGrid(){
 let start=TODAY,days=Array.from({length:5},(_,i)=>isoAdd(start,i)),hours=Array.from({length:18},(_,i)=>i+6);
 let head=days.map(d=>`<th>${new Intl.DateTimeFormat("th-TH",{weekday:"short",day:"numeric",month:"short"}).format(new Date(d+"T12:00:00"))}</th>`).join("");
 let rows=hours.map(h=>`<tr><th class="timeCell">${fmt(h)}</th>${days.map(d=>{let b=state.bookings.find(x=>x.date===d&&Number(x.start)<=h&&Number(x.end)>h&&!['cancelled','rejected_by_coach'].includes(x.status)),loc=state.coachLocations.find(x=>x.date===d&&Number(x.start)<=h&&Number(x.end)>h);if(b)return `<td><div class="coachClassCell"><b>${esc(b.athlete||b.athleteEmail||"Athlete")}</b><div>📍 ${esc(b.venue||"")}</div><div>☎ ${esc(b.phone||"ไม่มีเบอร์")}</div><span class="status ${b.status==='pending_coach_approval'?'pending':'confirmed'}">${esc(bookingStatusTH(b))}</span></div></td>`;if(loc)return `<td><div class="coachManualCell"><b>ตาราง Coach</b><div>📍 ${esc(loc.venueName||loc.venue||"")}</div></div></td>`;return `<td><div class="coachFreeCell">ว่าง</div></td>`}).join("")}</tr>`).join("");
 return `<div class="card"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap"><div><h3 style="margin:0">ตารางสอน 5 วัน</h3><div class=small>เห็นชื่อนักกีฬา สนาม และเบอร์โทรในแต่ละช่วงเวลา</div></div></div><div style="overflow:auto;margin-top:12px"><table class="tableSimple coachGrid"><thead><tr><th>เวลา</th>${head}</tr></thead><tbody>${rows}</tbody></table></div></div>`;
}
coachSchedule=function(){return `<h1 class=pageTitle>ตารางสอนของฉัน</h1><p class=muted>Booking ใหม่จะขึ้นในตารางทันทีในสถานะรอ Approve</p>${coachTeachingGrid()}${coachLocationEditor()}`}
function coachLocationEditor(){let locs=[...state.coachLocations].sort((a,b)=>String(a.date).localeCompare(String(b.date))||Number(a.start)-Number(b.start));return `<div class=card><h3>เพิ่มตารางสอน / ตารางเดิม</h3><div class=formgrid><label><span class=label>วันที่</span><input id=locDate class=field type=date min="${TODAY}" value="${TODAY}"></label><label><span class=label>สนาม</span><select id=locVenue class=field onchange="toggleCoachOtherVenue()">${state.venues.map(v=>`<option value="${esc(v.id)}">${esc(v.name)}</option>`).join("")}</select><input id=locOtherVenue class="field hidden" style="margin-top:8px" placeholder="ระบุชื่อสนามอื่น"></label><label><span class=label>เริ่ม</span><input id=locStart class=field type=time value="09:00"></label><label><span class=label>สิ้นสุด</span><input id=locEnd class=field type=time value="10:00"></label></div><button class="pill primary" style="margin-top:12px" onclick="saveCoachLocation()">+ เพิ่มลงตาราง</button><div id=locMsg></div></div>`}
coachBookings=function(){return `<h1 class=pageTitle>การจองที่รอการยืนยัน</h1><p class=muted>Coach ต้อง Approve ก่อน ระบบจึงส่งสถานะยืนยันกลับไปให้นักกีฬา</p>${bookingTable()}`}
renderAthleteBookings=function(){if(!athleteBookings)return;athleteBookings.innerHTML=state.bookings.filter(b=>b.athleteId===state.user?.uid).sort((a,b)=>String(b.createdAt||0).localeCompare(String(a.createdAt||0))).map(b=>`<div class=card><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><div><b>Booking ${esc(b.id)}</b><div>${thaiDate(b.date)} • ${fmt(b.start)}–${fmt(b.end)}</div><div>📍 ${esc(b.venue||"")}</div></div><span class="status ${["confirmed","coach_approved"].includes(b.status)?"confirmed":"pending"}">${esc(bookingStatusTH(b))}</span></div>${b.status==="coach_approved"?'<div class=ok style="margin-top:10px">✓ Coach ยืนยันการจองแล้ว</div>':b.status==="pending_coach_approval"?'<div class=notice style="margin-top:10px">กำลังรอ Coach Approve การจอง</div>':b.status==="rejected_by_coach"?`<div class=error style="margin-top:10px">${esc(b.coachApprovalReason||"Coach ไม่รับการจอง")}</div>`:""}</div>`).join("")||'<div class=muted>ยังไม่มีประวัติการจอง</div>'}


/* Sprint 3.5 — editable display names + profile photos */
function profileImagePickerHtml(id,current,label="รูปโปรไฟล์"){
 return `<div class="profilePhotoEditor"><div class="profilePreview">${current?`<img src="${current}" alt="${label}">`:`<span>👤</span>`}</div><div><div class="label">${label}</div><input id="${id}" class="field" type="file" accept="image/jpeg,image/png,image/webp"><div class="small">รองรับ JPG, PNG, WEBP • ระบบจะย่อรูปก่อนบันทึก</div></div></div>`;
}
async function fileToProfileDataUrl(file){
 if(!file)return ""; if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw new Error("กรุณาเลือกรูป JPG, PNG หรือ WEBP");
 const src=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});
 const img=await new Promise((res,rej)=>{let i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=src});
 const max=512,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);
 let out=c.toDataURL('image/jpeg',.78); if(out.length>420000)out=c.toDataURL('image/jpeg',.58); if(out.length>500000)throw new Error("รูปยังมีขนาดใหญ่เกินไป กรุณาเลือกรูปที่เล็กลง"); return out;
}
coachProfile=function(){let p=state.coachProfile||{};return `<h1 class=pageTitle>ประวัติโค้ช</h1><div class=card>${profileImagePickerHtml('coachPhotoFile',p.photoURL||'', 'รูปโปรไฟล์ Coach')}<div class=notice><b>Coach Di ID</b><div style="font-size:20px;font-weight:900;margin-top:4px">${p.coachDiId||"กำลังสร้าง..."}</div><div class=small>ID นี้ใช้ให้นักกีฬาค้นหาและเลือก Coach</div></div><div class=formgrid><label><span class=label>ชื่อที่แสดงในแอป *</span><input id=coachDisplayName class=field value="${esc(p.displayName||"")}" placeholder="เช่น Coach ตั้ม"></label><label><span class=label>ชื่อภาษาไทย</span><input id=coachNameTh class=field value="${esc(p.nameTh||"")}"></label><label><span class=label>ชื่อภาษาอังกฤษ</span><input id=coachNameEn class=field value="${esc(p.nameEn||"")}"></label><label><span class=label>Email</span><input class=field value="${esc(state.user?.email||"")}" disabled></label></div><label><span class=label>ประวัติแนะนำตัว</span><textarea id=coachBio class=field rows=4>${esc(p.bio||"")}</textarea></label><div style="margin-top:12px"><button class="pill primary" onclick="saveCoachProfile()">บันทึกโปรไฟล์</button></div></div>`}
saveCoachProfile=async function(){try{let name=coachDisplayName.value.trim();if(!name)throw new Error("กรุณาตั้งชื่อที่แสดงในแอป");let id=await ensureCoachDiId(state.user.uid),photo=state.coachProfile?.photoURL||"",f=coachPhotoFile.files?.[0];if(f)photo=await fileToProfileDataUrl(f);let next={coachDiId:id,displayName:name,nameTh:coachNameTh.value.trim(),nameEn:coachNameEn.value.trim(),bio:coachBio.value.trim(),photoURL:photo,status:state.coachProfile?.status||"draft",updatedAt:firebase.database.ServerValue.TIMESTAMP};await db.ref(`coachProfiles/${state.user.uid}`).update(next);state.coachProfile={...state.coachProfile,...next,updatedAt:Date.now()};await db.ref(`users/${state.user.uid}`).update({displayName:name,photoURL:photo});await audit("profile_changed",state.user.uid,{displayName:name,photoChanged:!!f});alert("บันทึกโปรไฟล์ Coach แล้ว");showCoach('profile')}catch(e){alert(e.message||"บันทึกโปรไฟล์ไม่สำเร็จ")}}
function athleteProfileView(){let u=state.userProfile||{};return `<div id="athleteProfilePanel"><div class="athleteHero card"><h1 class=pageTitle>โปรไฟล์นักกีฬา</h1><p class=muted>ตั้งชื่อและรูปที่ต้องการแสดงใน Coach Di</p></div><div class=card>${profileImagePickerHtml('athletePhotoFile',u.photoURL||'', 'รูปโปรไฟล์นักกีฬา')}<div class=formgrid><label><span class=label>ชื่อที่แสดงในแอป *</span><input id=athleteDisplayName class=field value="${esc(u.displayName||u.name||"")}" placeholder="เช่น หยก"></label><label><span class=label>Email</span><input class=field value="${esc(state.user?.email||"")}" disabled></label><label><span class=label>เบอร์โทร</span><input id=athleteProfilePhone class=field value="${esc(u.phone||"")}" placeholder="08x-xxx-xxxx"></label></div><button class="pill primary" style="margin-top:12px" onclick="saveAthleteProfile()">บันทึกโปรไฟล์</button></div></div>`}
async function saveAthleteProfile(captured){try{const history=window.CoachDiProfileHistory;if(!history)throw Error('โหลดระบบโปรไฟล์ไม่สำเร็จ กรุณารีเฟรชหน้า');const input=captured||history.capture(),uid=input.uid,next={...input.next};history.assertOwner(uid);if(input.file){next.photoURL=await fileToProfileDataUrl(input.file);next.photoStorage=null;}history.assertOwner(uid);const saved=await history.save(db,uid,next);history.assertOwner(uid);state.userProfile=saved;state.userDisplayName=saved.displayName||'';alert("บันทึกโปรไฟล์นักกีฬาแล้ว");showAthleteMenu('profile');return saved;}catch(e){alert(e.message||"บันทึกโปรไฟล์ไม่สำเร็จ");return null;}}
const _renderNav35=renderNav;renderNav=function(){_renderNav35();if(state.role==='athlete'){let side=document.getElementById('sidebar'),logout=side?.querySelector('.sideLogout');if(side&&!side.querySelector('[data-athlete-page="profile"]')){let b=document.createElement('button');b.className='navbtn';b.dataset.athletePage='profile';b.onclick=()=>showAthleteMenu('profile');b.innerHTML='<span class="navIcon">●</span>โปรไฟล์';side.insertBefore(b,logout||null)}}}
const _showAthleteMenu35=showAthleteMenu;showAthleteMenu=function(page){let ap=document.getElementById('athletePage');let old=document.getElementById('athleteProfilePanel');if(old)old.remove();Array.from(ap.children).forEach(x=>x.style.display='');if(page!=='profile')return _showAthleteMenu35(page);setAthleteNavActive('profile');athletePage.classList.remove('hidden');coachPage.classList.add('hidden');Array.from(ap.children).forEach(x=>x.style.display='none');ap.insertAdjacentHTML('beforeend',athleteProfileView());}
 const _loadFirebaseData35=loadFirebaseData;loadFirebaseData=async function(){await _loadFirebaseData35();if(state.role==='athlete'){let s=await db.ref(`users/${state.user.uid}`).once('value');state.userProfile=s.val()||{}}}

